$isi = $surat['isi_surat'] ?? ''; $nomor = $surat['nomor_surat'] ?? ''; $tanggal = $surat['tanggal_moc'] ?? date('Y-m-d');
function phk_value($label, $default = '') { global $isi, $surat; if (preg_match('/^' . preg_quote($label, '/') . '\\s*:\\s*(.+)$/im', $isi, $m)) return trim($m[1]); if ($label === 'Nama Karyawan' && !empty($surat['tujuan'])) return $surat['tujuan']; return $default; }
function phk_date($date) { $bulan = [1=>'Januari',2=>'Februari',3=>'Maret',4=>'April',5=>'Mei',6=>'Juni',7=>'Juli',8=>'Agustus',9=>'September',10=>'Oktober',11=>'November',12=>'Desember']; $time = strtotime($date) ?: time(); return date('j', $time) . ' ' . $bulan[(int)date('n', $time)] . ' ' . date('Y', $time); }
?>
<!doctype html><html lang="id"><head><meta charset="utf-8"><title>PHK - <?= htmlspecialchars($nomor) ?></title><style>@page{size:A4;margin:0}body{margin:0;font:12pt 'Times New Roman',serif}.page{width:210mm;min-height:297mm;margin:auto;padding:5mm 20mm 20mm;box-sizing:border-box}.kop{width:100%}.title{text-align:center;margin:12mm 0 7mm;font-weight:bold;text-decoration:underline;font-size:14pt}.number{text-align:center;margin-top:-5mm;margin-bottom:10mm}.recipient{line-height:1.5;margin-bottom:7mm}.body{line-height:1.6;text-align:justify}.body p{text-indent:12mm}.signature{width:70mm;margin:14mm 0 0 auto;text-align:center;line-height:1.5}.space{height:25mm}.actions{text-align:center;margin-top:10mm}.actions button{background:#e83e8c;color:#fff;border:0;border-radius:5px;padding:10px 18px;font-weight:700;cursor:pointer}@media print{.actions{display:none}}</style></head><body><main class="page"><img class="kop" src="<?= BASE_URL ?>/public/img/kop-surat.png"><div class="title">SURAT PEMUTUSAN HUBUNGAN KERJA</div><div class="number">Nomor: <?= htmlspecialchars($nomor) ?></div><div class="recipient">Kepada Yth.<br><strong><?= htmlspecialchars(phk_value('Nama Karyawan', '-')) ?></strong><br><?= htmlspecialchars(phk_value('Jabatan', '-')) ?><br>Di tempat</div><div class="body"><p>Dengan hormat, sehubungan dengan hubungan kerja Saudara/i di perusahaan, dengan ini kami memberitahukan bahwa hubungan kerja dinyatakan berakhir efektif sejak <strong><?= htmlspecialchars(phk_date(phk_value('Tanggal Efektif', $tanggal))) ?></strong>.</p><p>Data karyawan: Nomor Badge <?= htmlspecialchars(phk_value('Nomor Badge', '-')) ?>. Dasar keputusan ini adalah: <?= nl2br(htmlspecialchars(phk_value('Alasan', '-'))) ?>.</p><p>Kami mengucapkan terima kasih atas kontribusi dan kerja sama yang telah diberikan. Hak dan kewajiban yang masih berjalan akan diselesaikan sesuai ketentuan perusahaan dan peraturan yang berlaku.</p></div><div class="signature">Duri, <?= phk_date($tanggal) ?><br><?= htmlspecialchars(phk_value('Jabatan Penandatangan', 'Human Resources Department')) ?><div class="space"></div><strong><?= htmlspecialchars(phk_value('Penandatangan', 'HRD Department')) ?></strong></div><div class="actions"><button onclick="window.print()">Cetak Surat</button></div></main></body></html>
